javascript:
(function() {
  'use strict';

  // 教学假设参数
  const TEACHING_PARAMS = {
    granularity: [
      { label: '视网膜功能', opsPerBrain: 1e14, source: 'S017' },
      { label: '突触级别', opsPerBrain: 1e16, source: 'S017' },
      { label: '分子细节', opsPerBrain: 1e17, source: 'S017' }
    ],
    computerScale: [
      { label: '糖块大小', capacity: 1e21, source: 'S016' },
      { label: '行星质量', capacity: 1e42, source: 'S016' },
      { label: '戴森球', capacity: 1e50, source: 'S016' }
    ],
    humanHistory: {
      population: 100e9,
      yearsPerPerson: 50,
      secondsPerYear: 30e6
    }
  };

  // 状态管理
  let state = {
    granularityIndex: 1,
    scaleIndex: 2
  };

  // DOM 元素
  const elements = {
    granularitySlider: document.getElementById('granularity-slider'),
    scaleSlider: document.getElementById('computer-scale-slider'),
    granularityValue: document.getElementById('granularity-value'),
    scaleValue: document.getElementById('scale-value'),
    costBar: document.getElementById('cost-bar'),
    capacityBar: document.getElementById('capacity-bar'),
    costValue: document.getElementById('cost-value'),
    capacityValue: document.getElementById('capacity-value'),
    ratioValue: document.getElementById('ratio-value'),
    resetBtn: document.getElementById('reset-sim'),
    stepBtns: document.querySelectorAll('.step-btn'),
    stepDisplay: document.getElementById('substrate-step-display')
  };

  // 步骤内容
  const stepContent = [
    {
      text: '心理状态可以随 supervene 于广泛的物理基底之上，不仅限于碳基生物神经网络。',
      source: 'S007'
    },
    {
      text: '不需要行为完全像人（通过图灵测试），只需在足够精细的粒度（如突触级别）上结构性地复制计算过程。',
      source: 'S009'
    },
    {
      text: '神经递质等化学物质通过影响计算活动（如突触放电）来作用于体验，因此只要模拟了这些计算影响，无需模拟化学分子本身。',
      source: 'S011'
    }
  ];

  // 计算函数
  function calculateSimulationCost() {
    const opsPerBrain = TEACHING_PARAMS.granularity[state.granularityIndex].opsPerBrain;
    const totalOps = TEACHING_PARAMS.humanHistory.population * 
                     TEACHING_PARAMS.humanHistory.yearsPerPerson * 
                     TEACHING_PARAMS.humanHistory.secondsPerYear * 
                     opsPerBrain;
    return totalOps;
  }

  function getAvailableCapacity() {
    return TEACHING_PARAMS.computerScale[state.scaleIndex].capacity;
  }

  function formatScientific(num) {
    if (num === 0) return '0';
    const exponent = Math.floor(Math.log10(num));
    const mantissa = num / Math.pow(10, exponent);
    return mantissa.toFixed(1) + '×10^' + exponent;
  }

  // 更新显示
  function updateDisplay() {
    const cost = calculateSimulationCost();
    const capacity = getAvailableCapacity();
    const ratio = cost / capacity;

    // 更新滑块标签
    elements.granularityValue.textContent = TEACHING_PARAMS.granularity[state.granularityIndex].label;
    elements.scaleValue.textContent = TEACHING_PARAMS.computerScale[state.scaleIndex].label;

    // 更新条形图
    const maxDisplay = Math.max(cost, capacity);
    const costPercent = (cost / maxDisplay) * 100;
    const capacityPercent = (capacity / maxDisplay) * 100;

    elements.costBar.style.width = costPercent + '%';
    elements.capacityBar.style.width = capacityPercent + '%';

    // 更新数值显示
    elements.costValue.textContent = formatScientific(cost) + ' ops';
    elements.capacityValue.textContent = formatScientific(capacity) + ' ops';
    elements.ratioValue.textContent = formatScientific(ratio);
  }

  // 事件处理
  function handleGranularityChange(e) {
    state.granularityIndex = parseInt(e.target.value);
    updateDisplay();
  }

  function handleScaleChange(e) {
    state.scaleIndex = parseInt(e.target.value);
    updateDisplay();
  }

  function handleReset() {
    state.granularityIndex = 1;
    state.scaleIndex = 2;
    elements.granularitySlider.value = 1;
    elements.scaleSlider.value = 2;
    updateDisplay();
  }

  function handleStepChange(e) {
    const stepIndex = parseInt(e.target.dataset.step);

    // 更新按钮状态
    elements.stepBtns.forEach(btn => btn.classList.remove('active'));
    e.target.classList.add('active');

    // 更新显示内容
    const content = stepContent[stepIndex];
    elements.stepDisplay.innerHTML = `
      <p class="step-text">${content.text}</p>
      <div class="step-source">
        <button type="button" class="source-btn" data-source="${content.source}">原文 · p.${parseInt(content.source.substring(1))}</button>
      </div>
    `;

    // 重新绑定源按钮事件
    const sourceBtn = elements.stepDisplay.querySelector('.source-btn');
    if (sourceBtn) {
      sourceBtn.addEventListener('click', function() {
        // 源按钮行为由内核处理
        const event = new CustomEvent('paperMind:source', {
          detail: { sourceId: this.dataset.source }
        });
        document.dispatchEvent(event);
      });
    }
  }

  // 初始化
  function init() {
    // 绑定事件
    elements.granularitySlider.addEventListener('input', handleGranularityChange);
    elements.scaleSlider.addEventListener('input', handleScaleChange);
    elements.resetBtn.addEventListener('click', handleReset);

    elements.stepBtns.forEach(btn => {
      btn.addEventListener('click', handleStepChange);
    });

    // 绑定源按钮
    document.querySelectorAll('.source-btn').forEach(btn => {
      btn.addEventListener('click', function() {
        const event = new CustomEvent('paperMind:source', {
          detail: { sourceId: this.dataset.source }
        });
        document.dispatchEvent(event);
      });
    });

    // 初始显示
    updateDisplay();
  }

  // 启动
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
